package com.mengzhihua.crm.service.controller;
import com.mengzhihua.crm.common.*;import com.mengzhihua.crm.service.entity.KnowledgeArticle;import com.mengzhihua.crm.service.service.KnowledgeService;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/knowledge")public class KnowledgeController{private final KnowledgeService s;public KnowledgeController(KnowledgeService x){s=x;}@GetMapping public Result<PageResult<KnowledgeArticle>> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int size,@RequestParam(required=false)String keyword){return Result.ok(s.list(page,size,keyword));}@GetMapping("/{id}")public Result<KnowledgeArticle> get(@PathVariable Long id){return Result.ok(s.get(id));}@PostMapping public Result<KnowledgeArticle> add(@RequestBody KnowledgeArticle x){return Result.ok(s.save(x));}@PutMapping("/{id}")public Result<KnowledgeArticle> edit(@PathVariable Long id,@RequestBody KnowledgeArticle x){x.setId(id);return Result.ok(s.save(x));}@PutMapping("/{id}/publish")public Result<KnowledgeArticle> publish(@PathVariable Long id){return Result.ok(s.publish(id));}@DeleteMapping("/{id}")public Result<Void> del(@PathVariable Long id){s.delete(id);return Result.ok();}}
